export const isVectorShape = (t: string) => Object.prototype.hasOwnProperty.call(VECTOR_SHAPES, t);

type Op = [0, number, number] | [1, number, number] | [2, number, number, number, number, number, number] | [3];
const opsCache = new Map<string, Op[]>();
const opsOf = (t: string): Op[] => {
  let ops = opsCache.get(t);
  if (ops) return ops;
  ops = [];
  const toks = VECTOR_SHAPES[t].d.match(/[MLCZ]|-?\d*\.?\d+/g) || [];
  let cmd = '';
  for (let i = 0; i < toks.length; i++) {
    const k = toks[i];
    if (k === 'M' || k === 'L' || k === 'C') { cmd = k; continue; }
    if (k === 'Z') { ops.push([3]); continue; }
    if (cmd === 'M') { ops.push([0, +k, +toks[++i]]); cmd = 'L'; }
    else if (cmd === 'L') ops.push([1, +k, +toks[++i]]);
    else if (cmd === 'C') { ops.push([2, +k, +toks[i + 1], +toks[i + 2], +toks[i + 3], +toks[i + 4], +toks[i + 5]]); i += 5; }
  }
  opsCache.set(t, ops);
  return ops;
};

/** 把向量圖形接到 canvas 目前的路徑上：長邊 = size、以 (cx, cy) 為中心 */
export const traceVectorShape = (ctx: CanvasRenderingContext2D, t: string, cx: number, cy: number, size: number) => {
  const v = VECTOR_SHAPES[t], k = size / Math.max(v.w, v.h);
  const ox = cx - v.w * k / 2, oy = cy - v.h * k / 2;
  for (const o of opsOf(t)) {
    if (o[0] === 0) ctx.moveTo(ox + o[1] * k, oy + o[2] * k);
    else if (o[0] === 1) ctx.lineTo(ox + o[1] * k, oy + o[2] * k);
    else if (o[0] === 2) ctx.bezierCurveTo(ox + o[1] * k, oy + o[2] * k, ox + o[3] * k, oy + o[4] * k, ox + o[5] * k, oy + o[6] * k);
    else ctx.closePath();
  }
};
